// Content collections for /talks. Both are generated by the ingest pipeline
// (see ingest/ and intake/) — edit intake/*.md, not these files.
import { defineCollection } from "astro:content";
import { file, glob } from "astro/loaders";
import { z } from "astro/zod";

const talks = defineCollection({
  loader: file("src/data/talks.json", {
    parser: (text) => JSON.parse(text).map((t: { slug: string }) => ({ id: t.slug, ...t })),
  }),
  schema: z.object({
    slug: z.string(),
    title: z.string(),
    url: z.string().nullable(),
    platform: z.string(),
    date: z.string().nullable(),
    duration: z.number().nullable(),
    format: z.string().nullable(),
    event: z.string().nullable(),
    category: z.string().nullable(),
    topics: z.array(z.string()),
    thumbnail: z.string().nullable(),
    summary: z.string().nullable(),
    hasTranscript: z.boolean(),
  }),
});

const line = z.object({ t: z.number(), text: z.string() });

const transcripts = defineCollection({
  loader: glob({ pattern: "*.json", base: "src/content/transcripts" }),
  schema: z.object({
    slug: z.string(),
    scope: z.enum(["all", "ayman"]),
    format: z.string(),
    turns: z.array(
      z.object({
        speaker: z.string(),
        start: z.number(),
        end: z.number(),
        citable: z.boolean(),
        context: z.boolean(),
        lines: z.array(line),
      }),
    ),
  }),
});

export const collections = { talks, transcripts };
